export const RELEASE_VERSIONS = MINECRAFT_VERSIONS.filter((v) => v.type === 'release');
export const BETA_VERSIONS = MINECRAFT_VERSIONS.filter((v) => v.type === 'beta');
export const ALPHA_VERSIONS = MINECRAFT_VERSIONS.filter((v) => v.type === 'alpha');
export const SNAPSHOT_VERSIONS = MINECRAFT_VERSIONS.filter((v) => v.type === 'snapshot');

export function getVersionType(ver: string): 'release' | 'beta' | 'alpha' | 'snapshot' | 'unknown' {
  const found = MINECRAFT_VERSIONS.find((v) => v.version.toLowerCase() === ver.toLowerCase());
  if (found) return found.type;
  const l = ver.toLowerCase();
  if (l.startsWith('b1.') || l.startsWith('beta')) return 'beta';
  if (l.startsWith('a1.') || l.startsWith('alpha') || l.startsWith('c0.') || l.startsWith('inf-') || l.startsWith('rd-')) return 'alpha';
  if (l.includes('w') || l.includes('pre') || l.includes('rc') || l.includes('snapshot')) return 'snapshot';
  return 'release';
}
